export const FX_DEFAULTS={enabled:false,highpass:0,bass:0,presence:0,air:0,compress:false,threshold:-20,ratio:3,knee:10,attack:10,release:130,noise:0,noiseThreshold:-42,deess:0,output:0,limiter:false};
export const FX_PRESETS={neutral:{...FX_DEFAULTS,enabled:true},voice:{...FX_DEFAULTS,enabled:true,highpass:80,bass:-1,presence:2,compress:true,threshold:-21,ratio:3,deess:35,output:2},soft:{...FX_DEFAULTS,enabled:true,highpass:65,presence:1,compress:true,threshold:-18,ratio:2,deess:20,output:1},master:{...FX_DEFAULTS,enabled:true,compress:true,threshold:-16,ratio:2,attack:20,release:180,limiter:true}};
const ranges={highpass:[0,200],bass:[-12,12],presence:[-12,12],air:[-12,12],threshold:[-50,0],ratio:[1,12],knee:[0,24],attack:[1,100],release:[20,600],noise:[0,100],noiseThreshold:[-65,-20],deess:[0,100],output:[-24,12]};
export function cleanFx(raw={}){const fx={...FX_DEFAULTS};for(const k of ['enabled','compress','limiter'])fx[k]=raw[k]===true;for(const[k,[lo,hi]]of Object.entries(ranges))if(Number.isFinite(raw[k]))fx[k]=Math.max(lo,Math.min(hi,raw[k]));return fx;}
export class VoiceDSP{
 constructor(rate,raw){this.rate=rate;this.low=[];this.rms=0;this.highRms=0;this.comp=1;this.gate=1;this.lim=1;this.configure(raw);}
 configure(raw){this.fx=cleanFx(raw);const f=this.fx;this.rmsCoeff=1-Math.exp(-1/(.008*this.rate));this.attack=1-Math.exp(-1/(f.attack*.001*this.rate));this.release=1-Math.exp(-1/(f.release*.001*this.rate));this.lowCoeff=1-Math.exp(-2*Math.PI*4500/this.rate);this.makeup=10**(f.output/20);this.noiseFloor=10**(f.noiseThreshold/20);}
 process(input,output){const f=this.fx,n=output[0]?.length||0;for(let i=0;i<n;i++){let energy=0,highEnergy=0;for(let ch=0;ch<output.length;ch++){const x=input[ch]?.[i]??input[0]?.[i]??0;this.low[ch]=(this.low[ch]||0)+this.lowCoeff*(x-(this.low[ch]||0));const high=x-this.low[ch];energy+=x*x;highEnergy+=high*high;}this.rms+=this.rmsCoeff*(energy/output.length-this.rms);this.highRms+=this.rmsCoeff*(highEnergy/output.length-this.highRms);const rms=Math.sqrt(Math.max(0,this.rms)),db=20*Math.log10(Math.max(1e-9,rms));let reduction=0;if(f.compress){const over=db-f.threshold;if(f.knee>0&&Math.abs(over)<=f.knee/2)reduction=(1/f.ratio-1)*(over+f.knee/2)**2/(2*f.knee);else if(over>f.knee/2)reduction=(1/f.ratio-1)*over;}const target=10**(reduction/20);this.comp+=(target<this.comp?this.attack:this.release)*(target-this.comp);const gateTarget=f.noise?Math.max(10**(-f.noise*.36/20),Math.min(1,(rms/this.noiseFloor)**(1+f.noise/45))):1;this.gate+=(gateTarget>this.gate?.03:.0006)*(gateTarget-this.gate);const hiss=Math.sqrt(Math.max(0,this.highRms))/Math.max(.0001,rms),sibilance=Math.max(0,Math.min(1,(hiss-.28)*3))*Math.min(1,rms/.015)*f.deess/100*.8;let peak=0;for(let ch=0;ch<output.length;ch++){const x=input[ch]?.[i]??input[0]?.[i]??0;output[ch][i]=(x-(x-this.low[ch])*sibilance)*this.comp*this.gate*this.makeup;peak=Math.max(peak,Math.abs(output[ch][i]));}if(f.limiter){const targetLimit=peak>.89125?.89125/peak:1;this.lim=Math.min(targetLimit,this.lim+.00025*(1-this.lim));for(let ch=0;ch<output.length;ch++)output[ch][i]*=this.lim;}}return true;}
}
